//! The bundled VariableRenaming and IdeaNotNull plugins against the real plugin classes of the
//! Vineflower 1.12.0 release jar (`tests/data/kp1_plugins`, regenerated by its `gen.sh`):
//! the JAD and tiny name providers replayed call by call (`golden.txt`), and whole classes
//! decompiled with the plugins on under each `variants.tsv` option set.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};
use std::rc::Rc;

use kuna_jvm::classes_processor::{ClassNode, ClassNodeType};
use kuna_jvm::code_type::CodeType;
use kuna_jvm::decompiler_context::DecompilerContext;
use kuna_jvm::i_fernflower_preferences::IFernflowerPreferences;
use kuna_jvm::i_variable_name_provider::IVariableNameProvider;
use kuna_jvm::import_collector::ImportCollector;
use kuna_jvm::jad_name_provider::JADNameProvider;
use kuna_jvm::kuna_corpus::{run_case, with_engine_stack, Case, CaseStatus};
use kuna_jvm::pair::Pair;
use kuna_jvm::rt::jstring::from_utf16;
use kuna_jvm::rt::{try_catch, JLinkedHashMap};
use kuna_jvm::struct_class::StructClass;
use kuna_jvm::tiny_name_provider::{
    char_is_upper_case, char_to_lower_case, int_to_string_radix, TinyNameProvider,
};
use kuna_jvm::var_type::VarType;
use kuna_jvm::var_version_pair::VarVersionPair;

use crate::common;

fn data() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/data/kp1_plugins")
}

fn unesc(s: &str) -> Option<String> {
    if s == "\\N" {
        return None;
    }
    let mut units: Vec<u16> = Vec::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            units.push(c as u16);
            continue;
        }
        match chars.next() {
            Some('t') => units.push('\t' as u16),
            Some('n') => units.push('\n' as u16),
            Some('u') => {
                let hex: String = chars.by_ref().take(4).collect();
                units.push(u16::from_str_radix(&hex, 16).unwrap());
            }
            Some(other) => units.push(other as u16),
            None => units.push('\\' as u16),
        }
    }
    Some(from_utf16(&units))
}

fn esc(s: Option<&str>) -> String {
    let Some(s) = s else {
        return "\\N".to_string();
    };
    let mut out = String::new();
    for unit in s.encode_utf16() {
        match unit {
            0x5c => out.push_str("\\\\"),
            0x09 => out.push_str("\\t"),
            0x0a => out.push_str("\\n"),
            u if u > 0x7e => out.push_str(&format!("\\u{u:04x}")),
            u => out.push(u as u8 as char),
        }
    }
    out
}

fn code_type(name: &str) -> CodeType {
    match name {
        "BYTECHAR" => CodeType::Bytechar,
        "SHORTCHAR" => CodeType::Shortchar,
        "NULL" => CodeType::Null,
        "VOID" => CodeType::Void,
        "UNKNOWN" => CodeType::Unknown,
        "GENVAR" => CodeType::Genvar,
        other => panic!("code type {other}"),
    }
}

/// `N` = null, `@CODETYPE:dim:value`, or a descriptor (`new VarType(String)`).
fn var_type(enc: &str) -> Option<VarType> {
    if enc == "N" {
        return None;
    }
    if let Some(rest) = enc.strip_prefix('@') {
        let parts: Vec<&str> = rest.splitn(3, ':').collect();
        let dim: i32 = parts[1].parse().unwrap();
        return Some(if parts[2].is_empty() {
            VarType::new_dim(code_type(parts[0]), dim)
        } else {
            VarType::new_value(code_type(parts[0]), dim, parts[2])
        });
    }
    Some(VarType::new_signature(enc))
}

/// `!Class` for a caught exception.
fn failure(caught: kuna_jvm::rt::exception::Caught) -> String {
    let class = match &caught.exception {
        Some(e) => e.class.to_string(),
        None => caught
            .message
            .split(':')
            .next()
            .unwrap_or_default()
            .trim()
            .to_string(),
    };
    format!("!{class}")
}

#[derive(Clone)]
enum Provider {
    Jad(Rc<JADNameProvider>),
    Tiny(Rc<TinyNameProvider>),
}

impl Provider {
    fn dyn_(&self) -> Rc<dyn IVariableNameProvider> {
        match self {
            Provider::Jad(p) => p.clone(),
            Provider::Tiny(p) => p.clone(),
        }
    }
}

fn sorted_result(result: &kuna_jvm::rt::JHashMap<VarVersionPair, String>) -> String {
    let mut entries = result.entry_vec();
    entries.sort_by(|(a, _), (b, _)| (a.var, a.version).cmp(&(b.var, b.version)));
    entries
        .iter()
        .map(|(k, v)| format!("{}.{}={}", k.var, k.version, esc(Some(v))))
        .collect::<Vec<_>>()
        .join("|")
}

/// Java's `LinkedHashMap` keeps a `null` name, which `VarDefinitionHelper` reads as no rename.
fn without_null_names(expected: &str) -> String {
    expected
        .split('|')
        .filter(|e| !e.ends_with("=\\N"))
        .collect::<Vec<_>>()
        .join("|")
}

fn replay(naming: StructClass, ops: &[Vec<String>]) -> Vec<String> {
    let mut problems = Vec::new();
    let mut providers: BTreeMap<String, Provider> = BTreeMap::new();
    let mut current: Option<(String, String)> = None;
    for op in ops {
        let (engine, case) = (op[1].clone(), op[2].clone());
        if current.as_ref() != Some(&(engine.clone(), case.clone())) {
            providers.clear();
            if case == "parameters" {
                DecompilerContext::start_class(ImportCollector::new(ClassNode::new(
                    ClassNodeType::Root,
                    naming,
                )));
            }
            current = Some((engine.clone(), case.clone()));
        }
        let id = op[4].clone();
        let (got, want) = match op[3].as_str() {
            "new" => {
                let parts: Vec<&str> = op[5].split(' ').collect();
                let mt = naming
                    .get_method(parts[0], parts[1])
                    .unwrap_or_else(|| panic!("method {}", op[5]));
                let rp = op[6] == "1";
                let provider = if engine == "jad" {
                    Provider::Jad(Rc::new(JADNameProvider::new(rp, mt)))
                } else {
                    Provider::Tiny(Rc::new(TinyNameProvider::new(rp, mt)))
                };
                providers.insert(id, provider);
                continue;
            }
            "next" => {
                let provider = providers[&id].clone();
                let cast = unesc(&op[6]).unwrap();
                let type_ = var_type(&op[5]);
                let got = try_catch(|| match &provider {
                    Provider::Jad(p) => Some(p.get_new_name(&cast)),
                    Provider::Tiny(p) => p.get_new_name(Pair::of(type_, cast.clone())),
                });
                let got = match got {
                    Ok(name) => esc(name.as_deref()),
                    Err(caught) => failure(caught),
                };
                (got, op[7].clone())
            }
            "rename" => {
                let provider = providers[&id].dyn_();
                let mut entries: JLinkedHashMap<
                    VarVersionPair,
                    Pair<Option<VarType>, Option<String>>,
                > = JLinkedHashMap::new();
                for entry in unesc(&op[5]).unwrap().split('|') {
                    let fields: Vec<&str> = entry.splitn(3, '~').collect();
                    let (var, version) = fields[0].split_once('.').unwrap();
                    entries.put(
                        VarVersionPair::new(var.parse().unwrap(), version.parse().unwrap()),
                        Pair::of(var_type(fields[1]), Some(fields[2].to_string())),
                    );
                }
                let got = match try_catch(|| provider.rename(&entries)) {
                    Ok(result) => sorted_result(&result.expect("a renaming result")),
                    Err(caught) => failure(caught),
                };
                (got, without_null_names(&op[6]))
            }
            "param" => {
                let provider = providers[&id].dyn_();
                let flags: i32 = op[5].parse().unwrap();
                let type_ = var_type(&op[6]).unwrap();
                let name = unesc(&op[7]);
                let index: i32 = op[8].parse().unwrap();
                let got = match try_catch(|| {
                    provider.rename_parameter(flags, &type_, name.as_deref(), index)
                }) {
                    Ok(result) => esc(result.as_deref()),
                    Err(caught) => failure(caught),
                };
                (got, op[9].clone())
            }
            "parent" => {
                let child = providers[&id].dyn_();
                let parent = providers[&op[5]].dyn_();
                let got = match try_catch(|| child.add_parent_context(parent)) {
                    Ok(()) => "ok".to_string(),
                    Err(caught) => failure(caught),
                };
                (got, op[6].clone())
            }
            other => panic!("op {other}"),
        };
        if got != want {
            problems.push(format!("{}: got {got}", op.join("\t")));
        }
    }
    problems
}

fn golden() -> Vec<Vec<String>> {
    std::fs::read_to_string(data().join("golden.txt"))
        .expect("golden.txt")
        .lines()
        .map(|l| l.split('\t').map(str::to_string).collect())
        .collect()
}

#[test]
fn name_providers_match_the_plugin_classes() {
    let guard =
        common::install_context_with(&[(IFernflowerPreferences::INCLUDE_JAVA_RUNTIME, "0")]);
    let sc = guard.struct_context();
    sc.add_space_file(&data().join("classes"), true);
    let naming = sc.get_class("p/Naming").expect("p/Naming");
    let ops: Vec<Vec<String>> = golden().into_iter().filter(|l| l[0] == "op").collect();
    assert!(ops.len() > 300, "{} ops", ops.len());
    let problems = replay(naming, &ops);
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

#[test]
fn tiny_convert_to_name_matches() {
    let rows: Vec<Vec<String>> = golden().into_iter().filter(|l| l[0] == "convert").collect();
    assert!(rows.len() > 20);
    for row in rows {
        let idx: i32 = row[1].parse().unwrap();
        assert_eq!(
            esc(Some(&TinyNameProvider::convert_to_name(idx))),
            row[2],
            "convertToName({idx})"
        );
    }
    assert_eq!(int_to_string_radix(0, 26), "0");
    assert_eq!(int_to_string_radix(-27, 26), "-11");
}

#[test]
fn character_case_helpers_match_the_jdk() {
    let mut listed: BTreeMap<u16, (bool, u16)> = BTreeMap::new();
    for row in golden().into_iter().filter(|l| l[0] == "char") {
        let c = u16::from_str_radix(&row[1], 16).unwrap();
        listed.insert(
            c,
            (row[2] == "1", u16::from_str_radix(&row[3], 16).unwrap()),
        );
    }
    assert!(listed.len() > 1000);
    let mut problems = Vec::new();
    for c in 0..=0xFFFFu16 {
        let want = listed.get(&c).copied().unwrap_or((false, c));
        let got = (char_is_upper_case(c), char_to_lower_case(c));
        if got != want {
            problems.push(format!("{c:04x}: got {got:?}, Java {want:?}"));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

/// The test fixture's base map, the plugins on, then the variant's pairs.
fn variant_case(variant: &str, dir: &str, main: &str, pairs: &str) -> Case {
    let mut options: Vec<(String, String)> = [
        ("log-level", "warn"),
        ("decompile-generics", "1"),
        ("remove-synthetic", "1"),
        ("remove-bridge", "1"),
        ("keep-literals", "1"),
        ("__unit_test_mode__", "1"),
        ("new-line-separator", "1"),
        ("error-message", ""),
        ("include-runtime", ""),
        ("jvm_plugins", "1"),
    ]
    .iter()
    .map(|(k, v)| (k.to_string(), v.to_string()))
    .collect();
    for kv in pairs.split(';') {
        let (k, v) = kv.split_once('=').unwrap();
        kuna_jvm::kuna_corpus::overlay_option(&mut options, k, v);
    }
    let classes = data().join(dir).join("p");
    let mut siblings: Vec<PathBuf> = std::fs::read_dir(&classes)
        .unwrap()
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.file_name()
                .unwrap()
                .to_string_lossy()
                .starts_with(&format!("{main}$"))
        })
        .collect();
    siblings.sort();
    let mut class_files = vec![classes.join(format!("{main}.class"))];
    class_files.extend(siblings);
    Case {
        id: format!("kp1/{variant}/{main}"),
        set: variant.to_string(),
        set_slug: "kp1".to_string(),
        options,
        class_files,
        libraries: Vec::new(),
        expected: data()
            .join("expected")
            .join(variant)
            .join(format!("{main}.java")),
        compare: vec![format!("{main}.java")],
        javadoc: None,
        jdks: Vec::new(),
        fixes: None,
    }
}

#[test]
fn plugin_variants_match_vineflower() {
    let table = std::fs::read_to_string(data().join("variants.tsv")).unwrap();
    let cases: Vec<Case> = table
        .lines()
        .filter(|l| !l.starts_with('#') && !l.is_empty())
        .map(|l| {
            let f: Vec<&str> = l.split('\t').collect();
            variant_case(f[0], f[1], f[2], f[3])
        })
        .collect();
    assert_eq!(cases.len(), 12);
    let mut problems = Vec::new();
    for case in cases {
        let id = case.id.clone();
        let r = with_engine_stack(move || run_case(&case));
        if r.status != CaseStatus::Match {
            problems.push(format!(
                "{id}: {:?}, first difference {:?}, error {:?}",
                r.status, r.first_diff, r.error
            ));
        }
    }
    assert!(problems.is_empty(), "{}", problems.join("\n"));
}

#[test]
fn bundled_plugins_register_in_oracle_order_with_their_options() {
    let plugins = kuna_jvm::kuna_plugins::bundled_plugins();
    let ids: Vec<String> = plugins.iter().map(|p| p.id()).collect();
    assert_eq!(ids, ["VariableRenaming", "Kotlin", "IdeaNotNull"]);
    let options: Vec<(String, &str, Option<String>)> =
        kuna_jvm::kuna_plugins::bundled_plugin_options()
            .into_iter()
            .map(|o| (o.plugin, o.option.key, o.default))
            .collect();
    assert_eq!(
        options,
        [
            ("VariableRenaming".to_string(), "variable-renaming", None),
            (
                "VariableRenaming".to_string(),
                "rename-parameters",
                Some("0".to_string())
            ),
            (
                "VariableRenaming".to_string(),
                "jad-style-variable-naming",
                Some("0".to_string())
            ),
            (
                "VariableRenaming".to_string(),
                "jad-style-parameter-naming",
                Some("0".to_string())
            ),
            (
                "Kotlin".to_string(),
                "kt-show-public",
                Some("1".to_string())
            ),
            ("Kotlin".to_string(), "kt-enable", Some("1".to_string())),
            (
                "Kotlin".to_string(),
                "kt-unknown-defaults",
                Some("...".to_string())
            ),
            (
                "Kotlin".to_string(),
                "kt-collapse-string-concat",
                Some("1".to_string())
            ),
            (
                "Kotlin".to_string(),
                "kt-export-metadata",
                Some("0".to_string())
            ),
            (
                "Kotlin".to_string(),
                "kt-decompile-facades",
                Some("0".to_string())
            ),
            (
                "IdeaNotNull".to_string(),
                "resugar-idea-notnull",
                Some("1".to_string())
            ),
        ]
    );
}
